"use client";

import Link from "next/link";
import { useCart } from "@/context/CartContext";
import { useCallback, useState } from "react";

function formatPrice(n: number) {
  return "Rs. " + n.toLocaleString("en-PK");
}

function generateOrderId() {
  const prefix = "CHZ";
  const segment = () => Math.random().toString(36).slice(2, 6).toUpperCase();
  return `${prefix}-${segment()}-${segment()}`;
}

// Replace this with your real business WhatsApp number in international format without +
const WHATSAPP_NUMBER = "923001234567";

export default function CheckoutPage() {
  const { cart, totalPrice, clearCart } = useCart();
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [address, setAddress] = useState("");
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [orderId, setOrderId] = useState<string | null>(null);
  const [showSuccess, setShowSuccess] = useState(false);

  const validate = useCallback(() => {
    const next: Record<string, string> = {};
    if (!fullName.trim()) next.fullName = "Full name is required";
    if (!phone.trim()) next.phone = "Phone number is required";
    if (!address.trim()) next.address = "Delivery address is required";
    setErrors(next);
    return Object.keys(next).length === 0;
  }, [fullName, phone, address]);

  const handlePlaceOrder = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      if (!validate()) return;
      setIsSubmitting(true);

      const id = generateOrderId();
      const itemsSummary = cart
        .map((item) => `${item.name} x${item.quantity}`)
        .join(", ");

      const message = `New Order from Cheezious Web: ${itemsSummary}, Total: ${formatPrice(
        totalPrice
      )}, Address: ${address.trim()}`;

      const whatsappUrl = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(
        message
      )}`;

      if (typeof window !== "undefined") {
        window.open(whatsappUrl, "_blank", "noopener,noreferrer");
      }

      setOrderId(id);
      clearCart();
      setShowSuccess(true);
      setIsSubmitting(false);
    },
    [address, cart, totalPrice, validate, clearCart]
  );

  if (cart.length === 0 && !showSuccess) {
    return (
      <div className="min-h-screen bg-cheez-bg px-4 pt-24 pb-12">
        <div className="mx-auto max-w-lg rounded-3xl border border-white/50 bg-cheez-card p-8 text-center shadow-xl">
          <h1 className="text-xl font-bold text-cheez-ink">Your cart is empty</h1>
          <p className="mt-2 text-sm text-cheez-ink/70">
            Add some cheezy items before checking out.
          </p>
          <Link
            href="/"
            className="mt-6 inline-block rounded-full bg-cheez-red px-6 py-3 text-sm font-semibold uppercase tracking-wide text-cheez-white transition-colors hover:bg-[#d52f3b]"
          >
            Back to Menu
          </Link>
        </div>
      </div>
    );
  }

  if (showSuccess && orderId) {
    return (
      <div className="fixed inset-0 z-50 flex flex-col items-center justify-center bg-cheez-bg px-4">
        <div className="success-panel flex max-w-md flex-col items-center text-center">
          <div className="success-checkmark mb-6">
            <svg
              className="h-24 w-24 text-cheez-red"
              viewBox="0 0 52 52"
              aria-hidden
            >
              <circle
                className="success-circle"
                cx="26"
                cy="26"
                r="25"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
              />
              <path
                className="success-check"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M14.1 27.2l7.1 7.2 16.7-16.8"
              />
            </svg>
          </div>
          <h1 className="text-2xl font-black tracking-tight text-cheez-ink sm:text-3xl">
            Order placed!
          </h1>
          <p className="mt-2 text-cheez-ink/70">
            Thank you for ordering. We&apos;re getting your cheezy goodness ready.
          </p>
          <div className="mt-6 rounded-2xl border-2 border-dashed border-cheez-red/40 bg-cheez-red/5 px-6 py-4">
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-cheez-red">
              Order ID
            </p>
            <p className="mt-1 font-mono text-xl font-bold tracking-wide text-cheez-ink">
              {orderId}
            </p>
            <p className="mt-1 text-xs text-cheez-ink/60">
              Save this ID to track your order.
            </p>
          </div>
          <Link
            href="/"
            className="mt-8 rounded-full bg-cheez-red px-8 py-3 text-sm font-semibold uppercase tracking-[0.18em] text-cheez-white shadow-lg transition-colors hover:bg-[#d52f3b]"
          >
            Back to Home
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-cheez-bg">
      <header className="sticky top-0 z-30 border-b border-white/40 bg-cheez-bg/95 backdrop-blur-xl">
        <div className="mx-auto flex max-w-2xl items-center justify-between px-4 py-3">
          <Link
            href="/"
            className="text-sm font-semibold uppercase tracking-wide text-cheez-red hover:underline"
          >
            ← Back
          </Link>
          <span className="text-sm font-semibold text-cheez-ink">Checkout</span>
        </div>
      </header>

      <main className="mx-auto max-w-2xl px-4 py-8">
        <h1 className="text-2xl font-bold tracking-tight text-cheez-ink">
          Delivery details
        </h1>
        <p className="mt-1 text-sm text-cheez-ink/70">
          We&apos;ll use this to deliver your order.
        </p>

        <form onSubmit={handlePlaceOrder} className="mt-8 space-y-6">
          <div>
            <label
              htmlFor="fullName"
              className="block text-sm font-medium text-cheez-ink"
            >
              Full Name
            </label>
            <input
              id="fullName"
              type="text"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              placeholder="e.g. Ahmed Khan"
              className="mt-1.5 w-full rounded-xl border border-white/60 bg-cheez-card px-4 py-3 text-cheez-ink placeholder:text-cheez-ink/40 focus:border-cheez-red focus:outline-none focus:ring-2 focus:ring-cheez-red/20"
              autoComplete="name"
            />
            {errors.fullName && (
              <p className="mt-1 text-xs text-cheez-red">{errors.fullName}</p>
            )}
          </div>

          <div>
            <label
              htmlFor="phone"
              className="block text-sm font-medium text-cheez-ink"
            >
              Phone Number
            </label>
            <input
              id="phone"
              type="tel"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="e.g. 0300 1234567"
              className="mt-1.5 w-full rounded-xl border border-white/60 bg-cheez-card px-4 py-3 text-cheez-ink placeholder:text-cheez-ink/40 focus:border-cheez-red focus:outline-none focus:ring-2 focus:ring-cheez-red/20"
              autoComplete="tel"
            />
            {errors.phone && (
              <p className="mt-1 text-xs text-cheez-red">{errors.phone}</p>
            )}
          </div>

          <div>
            <label
              htmlFor="address"
              className="block text-sm font-medium text-cheez-ink"
            >
              Delivery Address
            </label>
            <textarea
              id="address"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              placeholder="Street, area, city, and landmark"
              rows={3}
              className="mt-1.5 w-full resize-none rounded-xl border border-white/60 bg-cheez-card px-4 py-3 text-cheez-ink placeholder:text-cheez-ink/40 focus:border-cheez-red focus:outline-none focus:ring-2 focus:ring-cheez-red/20"
              autoComplete="street-address"
            />
            {errors.address && (
              <p className="mt-1 text-xs text-cheez-red">{errors.address}</p>
            )}
          </div>

          <div className="rounded-2xl border border-white/50 bg-cheez-card/80 p-4">
            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-cheez-ink/70">
              Order summary
            </p>
            <ul className="mt-2 space-y-1 text-sm text-cheez-ink">
              {cart.map((item) => (
                <li key={item.id} className="flex justify-between">
                  <span>
                    {item.name} × {item.quantity}
                  </span>
                  <span>{formatPrice(item.priceNumber * item.quantity)}</span>
                </li>
              ))}
            </ul>
            <div className="mt-3 flex justify-between border-t border-white/40 pt-3 text-lg font-bold text-cheez-ink">
              <span>Subtotal</span>
              <span>{formatPrice(totalPrice)}</span>
            </div>
          </div>

          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full rounded-full bg-cheez-red py-4 text-sm font-semibold uppercase tracking-[0.18em] text-cheez-white shadow-lg transition-colors hover:bg-[#d52f3b] disabled:opacity-70"
          >
            {isSubmitting ? "Placing order…" : "Place Order"}
          </button>
        </form>
      </main>
    </div>
  );
}
